(function() {
  window.CardSpoke.registerPlugin('card-color-tags', {
    manifest: {
      name: 'Card Color Tags',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'Adds a colored left border to each card based on its first tag',
      layer: 'feature',
      permissions: []
    },
    setup: async function(ctx) {
      var self = this;
      var palette = [
        '#e74c3c', '#3498db', '#2ecc71', '#f39c12', '#9b59b6',
        '#1abc9c', '#e67e22', '#e84393', '#0984e3', '#6c5ce7'
      ];
      var tagColorMap = {};
      var colorIndex = 0;
      function getTagColor(tag) {
        if (!tag) return '#999';
        if (!tagColorMap[tag]) {
          tagColorMap[tag] = palette[colorIndex % palette.length];
          colorIndex++;
        }
        return tagColorMap[tag];
      }
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.register({
          name: 'card-color-tags-render',
          priority: 5,
          operations: ['card.render'],
          handler: async function(mwCtx, next) {
            await next();
            var card = mwCtx.args[0];
            var element = mwCtx.args[1];
            if (!card || !element) return;
            if (card.tags && card.tags.length > 0) {
              var color = getTagColor(card.tags[0]);
              element.setAttribute('data-color-tag', card.tags[0]);
              element.style.setProperty('--tag-color', color);
            } else {
              element.removeAttribute('data-color-tag');
            }
          }
        });
      }
      var legend = document.createElement('div');
      legend.className = 'color-tag-legend';
      legend.id = 'color-tag-legend';
      function updateLegend() {
        var cards = ctx.api.data.listCards();
        var seenTags = {};
        cards.forEach(function(c) {
          if (c.tags && c.tags.length > 0 && !seenTags[c.tags[0]]) {
            seenTags[c.tags[0]] = getTagColor(c.tags[0]);
          }
        });
        var html = '';
        Object.keys(seenTags).forEach(function(tag) {
          html += '<div class="color-tag-legend-item">';
          html += '<span class="color-tag-legend-swatch" style="background:' + seenTags[tag] + '"></span>';
          html += '<span>' + tag + '</span></div>';
        });
        legend.innerHTML = html || '<em>No tagged cards</em>';
      }
      updateLegend();
      document.body.appendChild(legend);
      self._legend = legend;
      self._updateLegend = updateLegend;
      ctx.logger.info('Card Color Tags loaded');
    },
    teardown: async function(ctx) {
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.unregister('card-color-tags-render');
      }
      if (this._legend && this._legend.parentNode) {
        this._legend.remove();
      }
      var tagged = document.querySelectorAll('[data-color-tag]');
      tagged.forEach(function(el) {
        el.removeAttribute('data-color-tag');
        el.style.removeProperty('--tag-color');
      });
      ctx.logger.info('Card Color Tags disabled');
    }
  });
})();
